// Park logos for the offer PDF (from build/logos; JPEG, base64). Generated — do not edit by hand.
export const LOGOS: Record<string, { w: number; h: number; c: number; b64: string }> = {
  oct: { w: 358, h: 135, c: 3, b64: "" },
  borg: { w: 358, h: 135, c: 3, b64: "" },
  asher: { w: 358, h: 135, c: 3, b64: "" },
  east: { w: 358, h: 135, c: 3, b64: "" },
  newsadat: { w: 358, h: 135, c: 3, b64: "" },
  sadat: { w: 358, h: 135, c: 3, b64: "" },
  sokhna: { w: 358, h: 135, c: 3, b64: "" },
  oula: { w: 358, h: 135, c: 3, b64: "" },
  s360: { w: 360, h: 360, c: 3, b64: "" },
  sdm: { w: 438, h: 164, c: 3, b64: "" },
};
/** which logo a Land Bank park uses (same parks as the Land Bank offer) */
export function logoKey(park: string): string {
  const p = (park || "").toLowerCase();
  if (/october/.test(p)) return "oct"; if (/borg/.test(p)) return "borg"; if (/asher/.test(p)) return "asher"; if (/east/.test(p)) return "east";
  if (/new sadat/.test(p)) return "newsadat"; if (/sadat/.test(p)) return "sadat"; if (/360/.test(p)) return "s360"; if (/sokhna/.test(p)) return "sokhna";
  if (/oula/.test(p)) return "oula"; return "sdm";
}
